  'Playback' => 'प्लेबॅक',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'प्रमाणीकृत प्लॅटफॉर्म वैशिष्ट्यांशी लिंक केल्यावर प्लेबॅक प्रगती, नंतर पाहण्याची स्थिती, पसंती, टिप्पण्या, सदस्यता, सूचना आणि प्रशासक विश्लेषणे डेटाबेसमध्ये संग्रहित केली जातात.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'प्लेबॅक, टिप्पण्या, पसंती, नंतर पहा, सदस्यता, सूचना, संदेश, प्लेलिस्ट आणि भाषा सेटिंग्ज मुख्य नेव्हिगेशन आणि खाते मेनूद्वारे उपलब्ध आहेत.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub हे एका खात्यातून निर्माता सामग्री अपलोड करणे, पाहणे, शेड्यूल करणे, व्यवस्थापित करणे आणि नियंत्रित करणे यासाठी एक व्हिडिओ प्लॅटफॉर्म आहे.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub हे या उपयोजनावर चालणारे व्हिडिओ प्लॅटफॉर्म आहे, जे निर्माते, दर्शक, समुदाय आणि प्लॅटफॉर्म ऑपरेटरसाठी तयार केले आहे.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub एका प्लॅटफॉर्मवरून निर्माता चॅनेल, व्हिडिओ अपलोड, शेड्यूल केलेले प्रकाशन, सदस्यता, टिप्पण्या, प्लेलिस्ट, नंतर पहा, थेट सामग्री पृष्ठे आणि प्रशासन साधने प्रदान करते.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub लॉगिन सत्र, API प्रमाणीकरण, CSRF/सुरक्षा वर्तन, भाषा निवड, थीम निवड, खाते मेनू स्थिती आणि अनुप्रयोग कार्य करण्यासाठी आवश्यक असलेल्या इतर वैशिष्ट्यांसाठी आवश्यक कुकीज आणि ब्राउझर संचयन वापरते.',
