  'Required for login, security, and app routing.' => 'लॉगिन, सुरक्षितता आणि ॲप राउटिंगसाठी आवश्यक.',
  'Response targets' => 'प्रतिसाद लक्ष्य',
  'Retention and access' => 'धारणा आणि प्रवेश',
  'Review privacy and cookie details for this deployment.' => 'या तैनातीसाठी गोपनीयता आणि कुकी तपशीलांचे पुनरावलोकन करा.',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'हे PlayHub उपयोजन दर्शक, निर्माता किंवा प्रशासक म्हणून वापरण्याचे नियम.',
  'Safety' => 'सुरक्षितता',
  'Safety / technical' => 'सुरक्षा / तांत्रिक',
  'Safety and content reports' => 'सुरक्षा आणि सामग्री अहवाल',
  'Safety or report' => 'सुरक्षितता किंवा अहवाल',
  'Sample endpoints' => 'नमुना अंतिम बिंदू',
  'sample endpoints loaded' => 'नमुना अंतिम बिंदू लोड केले',
  'Schedule video' => 'व्हिडिओ शेड्यूल करा',
  'Scheduled video release and reminders.' => 'शेड्यूल केलेले व्हिडिओ रिलीझ आणि स्मरणपत्रे.',
  'Scheduled videos' => 'शेड्यूल केलेले व्हिडिओ',
  'Scheduling a video release' => 'व्हिडिओ रिलीज शेड्यूल करत आहे',
  'Search for answers...' => 'उत्तरे शोधा...',
  'Search help articles, topics, or questions...' => 'मदत लेख, विषय किंवा प्रश्न शोधा...',
  'Select a reason' => 'एक कारण निवडा',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'एक किंवा अधिक व्हिडिओ फाइल्स निवडा, आवश्यक तपशील प्रविष्ट करा, श्रेणी आणि भाषा निवडा, लघुप्रतिमा जोडा, दृश्यमानता निवडा आणि प्रकाशित करा. सर्व्हरने प्रक्रिया सुरू करण्यापूर्वी मोठ्या फायली भागांमध्ये अपलोड केल्या जातात.',
  'Send a message and it will be saved for admins.' => 'एक संदेश पाठवा आणि तो प्रशासकांसाठी जतन केला जाईल.',
  'Send billing details to admin support for review.' => 'पुनरावलोकनासाठी प्रशासक समर्थनास बिलिंग तपशील पाठवा.',
  'Send message' => 'संदेश पाठवा',
  'Send order details through the refund popup.' => 'परतावा पॉपअपद्वारे ऑर्डर तपशील पाठवा.',
  'Send us a message' => 'आम्हाला एक संदेश पाठवा',
  'Sending...' => 'पाठवत आहे...',
  'Server configured' => 'सर्व्हर कॉन्फिगर केले',
  'server records' => 'सर्व्हर रेकॉर्ड',
  'Service operation' => 'सेवा ऑपरेशन',
  'session, token' => 'सत्र, टोकन',
  'Settings and login' => 'सेटिंग्ज आणि लॉगिन',
  'Short summary' => 'थोडक्यात सारांश',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'साइन इन करा आणि खाते, प्रोफाइल, पासवर्ड, सूचना, गोपनीयता आणि निर्माता प्राधान्यांसाठी सेटिंग्ज वापरा. निर्माता अपलोड आणि सामग्री समस्यांमध्ये व्हिडिओ शीर्षक, चॅनेल, ब्राउझर आणि अपलोड पृष्ठावर दर्शविलेली कोणतीही प्रक्रिया त्रुटी समाविष्ट असावी.',
  'Sign in for account support' => 'खाते समर्थनासाठी साइन इन करा',
  'Signed in' => 'साइन इन केले',
  'Start uploading' => 'अपलोड करणे सुरू करा',
  'Still can’t find an answer?' => 'अद्याप उत्तर सापडत नाही?',
  'Stored for admins' => 'प्रशासकांसाठी संग्रहित',
  'Stores language, theme, and interface preferences.' => 'भाषा, थीम आणि इंटरफेस प्राधान्ये संग्रहित करते.',
  'Studio, playlists, analytics, channels.' => 'स्टुडिओ, प्लेलिस्ट, विश्लेषणे, चॅनेल.',
  'Submit a billing or refund message to admin support.' => 'प्रशासक समर्थनासाठी बिलिंग किंवा परतावा संदेश सबमिट करा.',
  'Submit refund request' => 'परतावा विनंती सबमिट करा',
  'Submit request' => 'विनंती सबमिट करा',
  'Subscription cancellation' => 'सदस्यता रद्द करणे',
  'Support dashboard' => 'समर्थन डॅशबोर्ड',
  'System status' => 'सिस्टम स्थिती',
  'Table' => 'टेबल',
  'Taxonomies' => 'वर्गीकरण',
  'Technical issue' => 'तांत्रिक समस्या',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'सध्याच्या PlayHub API आणि अपलोड वर्कफ्लोसह एकत्रीकरणासाठी तांत्रिक टिपा.',
  'Tell us more about your question or request...' => 'तुमच्या प्रश्न किंवा विनंतीबद्दल आम्हाला अधिक सांगा...',
  'Terms of Use' => 'वापराच्या अटी',
  'The configured' => 'कॉन्फिगर केलेले',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'डेव्हलपर पेज लाईव्ह लारावेल बॅकएंडशी जोडलेले आहे: रूट इन्व्हेंटरी, डेटाबेस संख्या, अपलोड मर्यादा आणि प्लॅटफॉर्म मेटाडेटा /api/developers वरून लोड केले जातात.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'फ्रंटएंड निवडलेली भाषा, थीम, प्लेबॅक रांग, प्रगती पाहणे आणि इंटरफेस स्थिती यांसारखी प्राधान्ये संग्रहित करते जेणेकरून अनुभव पृष्ठ नेव्हिगेशन आणि रीलोडवर सुसंगत राहतो.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'प्रोसेसिंग जॉब प्रस्तुतीकरण एन्कोड करते, आवश्यकतेनुसार लघुप्रतिमा तयार करते, मथळे संग्रहित करते आणि प्रक्रिया पूर्ण झाल्यावर व्हिडिओ तयार चिन्हांकित करते. शेड्युलर रिलीझ करेपर्यंत भविष्यातील शेड्यूल केलेले व्हिडिओ खाजगी राहतात.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'अपलोड सिस्टम डेटाबेस-बॅक्ड आहे, API मधील श्रेण्या आणि भाषांना समर्थन देते, अपलोड केलेल्या व्हिडिओंवर प्रक्रिया करते, लघुप्रतिमा आणि मथळे संग्रहित करते आणि शेड्यूल केलेली सामग्री तिच्या प्रकाशन वेळेपर्यंत खाजगी ठेवते.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'हे पृष्ठ सत्र, सुरक्षा, प्राधान्ये, प्लेबॅक आणि प्रमाणीकृत वैशिष्ट्यांसाठी PlayHub कुकीज आणि ब्राउझर संचयन कसे वापरते हे स्पष्ट करते.',
  'Ticket source' => 'तिकीट स्त्रोत',
  'Top content categories' => 'शीर्ष सामग्री श्रेणी',
  'Topic' => 'विषय',
  'Transaction / invoice' => 'व्यवहार / बीजक',
  'Transaction / invoice ID' => 'व्यवहार / बीजक आयडी',
  'Unable to send message.' => 'संदेश पाठवण्यात अक्षम.',
  'Unable to submit refund request.' => 'परतावा विनंती सबमिट करण्यात अक्षम.',
  'Understanding admin support tickets' => 'प्रशासक समर्थन तिकिटे समजून घेणे',
  'Upload and processing help' => 'अपलोड आणि प्रक्रिया मदत',
  'Upload chunks' => 'भाग अपलोड करा',
  'Upload issues' => 'समस्या अपलोड करा',
  'Upload languages' => 'भाषा अपलोड करा',
  'Upload limit' => 'अपलोड मर्यादा',
  'Upload options' => 'अपलोड पर्याय',
  'Upload or processing' => 'अपलोड किंवा प्रक्रिया',
  'Upload page' => 'पृष्ठ अपलोड करा',
  'Upload pipeline' => 'पाइपलाइन अपलोड करा',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'थेट PlayHub डेटासह अपलोड करा, पहा, सदस्यता घ्या, नियंत्रित करा आणि तयार करा.',
  'Uploaded videos' => 'अपलोड केलेले व्हिडिओ',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'अपलोड केलेले व्हिडिओ प्ले करण्यायोग्य प्रस्तुतीकरणांमध्ये एन्कोड केलेले आहेत. प्रक्रिया वेळ फाईल आकार, कालावधी, सर्व्हर लोड आणि रांगेच्या स्थितीवर अवलंबून असते. अपलोड पृष्ठ आणि क्रिएटर स्टुडिओ व्हिडिओ रेकॉर्डमधून वास्तविक प्रक्रिया स्थिती दर्शवतात.',
  'Uploads, scheduling, and processing are available.' => 'अपलोड, शेड्युलिंग आणि प्रक्रिया उपलब्ध आहेत.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'क्रिएटर वर्कफ्लोसाठी /api/व्हिडिओ, चॅनल एंडपॉइंट आणि ऑथेंटिकेटेड मार्ग वापरा.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'व्हिडिओ आणि टिप्पण्यांसाठी अंगभूत अहवाल क्रिया वापरा जेणेकरून प्रशासकांना अचूक सामग्री संदर्भ प्राप्त होईल. प्रशासन डॅशबोर्ड पृष्ठे वापरकर्ते, सामग्री, अहवाल, कमाई, विश्लेषण, समर्थन, भूमिका आणि सिस्टम सेटिंग्जसाठी थेट डेटाबेस डेटा वापरतात.',
  'Use Contact Us' => 'आमच्याशी संपर्क साधा वापरा',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'सामान्य API विनंत्यांसाठी JSON आणि फाइल अपलोडसाठी FormData वापरा. प्रमाणीकरण बायपास करू नका: श्रेण्या आणि भाषा डेटाबेस आयडी आहेत, दृश्यमानता सार्वजनिक, असूचीबद्ध किंवा खाजगी मर्यादित आहे आणि मथळे SRT, VTT किंवा TXT फायली स्वीकारतात.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'तुमचे प्रोफाइल, सुरक्षा, पासवर्ड, द्वि-घटक वितरण, डिव्हाइसेस, प्राधान्ये आणि सूचना पर्याय अपडेट करण्यासाठी सेटिंग्ज वापरा. आपण आपल्या खात्यात प्रवेश करू शकत नसल्यास, लॉगिन प्रवाह वापरा आणि साइट प्रशासकाला खाते ईमेल प्रदान करा.',
  'Use the contact form' => 'संपर्क फॉर्म वापरा',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'व्हिडिओ, टिप्पण्या आणि समुदाय पोस्टवर अहवाल क्रिया वापरा जेणेकरून प्रशासकांना अचूक सामग्री संदर्भ प्राप्त होईल.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'जेव्हा सामग्री प्लॅटफॉर्म नियमांचे उल्लंघन करू शकते तेव्हा व्हिडिओ, टिप्पण्या आणि समुदाय पोस्टवरील अहवाल क्रिया वापरा. हे अहवाल वास्तविक सामग्री रेकॉर्डशी जोडलेले आहेत आणि सामान्य संदेशापेक्षा चांगले आहेत कारण प्रशासक अचूक आयटमचे पुनरावलोकन करू शकतात.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'खाते मदत, सामग्री अहवाल, तांत्रिक समस्या आणि प्रशासक विनंत्यांसाठी योग्य PlayHub चॅनेल वापरा.',
  'Video categories' => 'व्हिडिओ श्रेणी',
  'Video for everyone. Built for creators and viewers.' => 'प्रत्येकासाठी व्हिडिओ. रिअल प्लॅटफॉर्म डेटावरून तयार केलेले.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'व्हिडिओ अपलोड, शेड्युलिंग, लघुप्रतिमा आणि प्रक्रिया समस्या.',
  'Videos, thumbnails, captions, processing.' => 'व्हिडिओ, लघुप्रतिमा, मथळे, प्रक्रिया.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'दर्शक श्रेणी ब्राउझ करू शकतात, व्हिडिओ शोधू शकतात, सामग्री पाहू शकतात, चॅनेलची सदस्यता घेऊ शकतात, नंतर पाहण्यासाठी व्हिडिओ सेव्ह करू शकतात, टिप्पणी करू शकतात, सूचना प्राप्त करू शकतात आणि भाषा आणि प्रवेशयोग्यता प्राधान्ये व्यवस्थापित करू शकतात.',
  'Viewing and community help' => 'पाहणे आणि समुदाय मदत',
  'Waiting for backend endpoint inventory.' => 'बॅकएंड एंडपॉइंट इन्व्हेंटरीची प्रतीक्षा करत आहे.',
  'We’re here to help.' => 'आम्ही मदत करण्यासाठी येथे आहोत.',
  'What is PlayHub?' => 'PlayHub म्हणजे काय?',
  'What PlayHub does' => 'PlayHub काय करते',
  'Where do contact messages go?' => 'संपर्क संदेश कुठे जातात?',
  'Why is my video still processing?' => 'माझा व्हिडिओ अद्याप प्रक्रिया का करत आहे?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'होय. अपलोड पृष्ठावरील मूळ शेड्यूल तारीख आणि वेळ फील्ड वापरा. बॅकएंड शेड्यूल_एट संचयित करते, व्हिडिओवर प्रक्रिया करते, तारीख भविष्यात असताना खाजगी ठेवते आणि जेव्हा Laravel शेड्यूलर नियोजित वेळेनंतर चालते तेव्हा ते रिलीज करते.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'होय. अपलोडवर नेटिव्ह शेड्यूल फील्ड वापरा. बॅकएंड शेड्यूल_एट स्टोअर करते आणि शेड्यूलची वेळ पूर्ण झाल्यावर प्रक्रिया केल्यानंतर व्हिडिओ रिलीज करते.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'You are browsing as a guest. खाते-विशिष्ट साधनांमध्ये प्रवेश करण्यासाठी साइन इन करा.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'तुम्ही तुमचे खाते क्रेडेंशियल्स, प्रोफाइल ॲक्टिव्हिटी, अपलोड केलेली सामग्री, टिप्पण्या, संदेश आणि तुमच्या खात्यातून केलेल्या कोणत्याही निर्मात्या किंवा प्रशासकाच्या कृतींसाठी जबाबदार आहात. मजबूत पासवर्ड वापरा आणि द्वि-घटक वितरण पद्धती चालू ठेवा.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'तुम्ही तुमच्या ब्राउझर सेटिंग्जमध्ये ब्राउझर कुकीज आणि स्थानिक स्टोरेज साफ करू शकता. अत्यावश्यक स्टोरेज साफ केल्याने तुम्ही साइन आउट करू शकता, भाषा/थीम प्राधान्ये रीसेट करू शकता, स्थानिक प्लेबॅक स्थिती काढून टाकू शकता आणि तुम्हाला पुन्हा लॉग इन करणे आवश्यक आहे.',
